<?php
namespace Pterodactyl\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Illuminate\Support\Str; use Pterodactyl\Services\Nodexa\FlaxVpsClient;
class ClientAreaController { public function index(Request $r){$u=$r->user();abort_unless($u,401);$services=Schema::hasTable('servers')?DB::table('servers')->where('owner_id',$u->id)->orderByDesc('id')->get():collect();$vpsServices=Schema::hasTable('vps_services')?DB::table('vps_services')->where('user_id',$u->id)->orderByDesc('id')->get():collect();$invoices=Schema::hasTable('invoices')?DB::table('invoices')->where('user_id',$u->id)->orderByDesc('id')->limit(8)->get():collect();$tickets=Schema::hasTable('tickets')?DB::table('tickets')->where('user_id',$u->id)->orderByDesc('updated_at')->get():collect();$products=Schema::hasTable('billing_products')?DB::table('billing_products')->where('active',true)->orderBy('price')->get():collect();return view('client.index',compact('u','services','vpsServices','invoices','tickets','products'))->with('user',$u);} private function ownedVps(Request $r,int $id){$v=DB::table('vps_services')->where('id',$id)->where('user_id',$r->user()->id)->first();abort_unless($v,404);return $v;} public function vps(Request $r,int $id){$v=$this->ownedVps($r,$id);$info=[];$oses=[];$apiError=null;if($v->provider_server_id){try{$api=new FlaxVpsClient();$info=$api->info((string)$v->provider_server_id);$oses=$api->discoverOperatingSystems();}catch(\Throwable $e){$apiError=$e->getMessage();}}return view('client.vps',['user'=>$r->user(),'vps'=>$v,'info'=>$info,'oses'=>$oses,'apiError'=>$apiError]);} public function vpsPower(Request $r,int $id){$v=$this->ownedVps($r,$id);abort_unless($v->provider_server_id,422);$d=$r->validate(['action'=>'required|in:boot,shutdown,restart,poweroff']);try{(new FlaxVpsClient())->power((string)$v->provider_server_id,$d['action']);return back()->with('success','VPS-handlingen blev sendt til serveren.');}catch(\Throwable $e){return back()->withErrors(['vps'=>$e->getMessage()]);}} public function vpsRebuild(Request $r,int $id){$v=$this->ownedVps($r,$id);abort_unless($v->provider_server_id,422);$d=$r->validate(['os_id'=>'required|string|max:100','confirm'=>'required|in:REINSTALL']);try{(new FlaxVpsClient())->rebuild((string)$v->provider_server_id,$d['os_id']);DB::table('vps_services')->where('id',$v->id)->update(['os_id'=>$d['os_id'],'updated_at'=>now()]);return back()->with('success','Geninstallation er startet. Alt eksisterende data på VPS’en bliver slettet.');}catch(\Throwable $e){return back()->withErrors(['vps'=>$e->getMessage()]);}} public function vpsResetPassword(Request $r,int $id){$v=$this->ownedVps($r,$id);abort_unless($v->provider_server_id,422);$d=$r->validate(['user'=>'nullable|string|max:64']);try{$result=(new FlaxVpsClient())->resetPassword((string)$v->provider_server_id,$d['user']?:'root');$password=$result['password']??$result['new_password']??$result['newPassword']??null;return back()->with('success',$password?'Adgangskoden er nulstillet. Ny adgangskode: '.$password:'Adgangskoden er nulstillet hos Flax.');}catch(\Throwable $e){return back()->withErrors(['vps'=>$e->getMessage()]);}} public function orderPage(Request $r,int $product){$p=DB::table('billing_products')->where('id',$product)->where('active',true)->first();abort_unless($p,404);$oses=collect();$osError=null;if(($p->product_type??'game')==='vps'){try{$oses=(new FlaxVpsClient())->discoverOperatingSystems();}catch(\Throwable $e){$osError=$e->getMessage();}}$gateways=Schema::hasTable('payment_gateways')?DB::table('payment_gateways')->where('enabled',true)->orderBy('sort_order')->get():collect();return view('client.order',['product'=>$p,'user'=>$r->user(),'oses'=>$oses,'osError'=>$osError,'gateways'=>$gateways]);} public function order(Request $r){$u=$r->user();abort_unless($u,401);$d=$r->validate(['product_id'=>'required|integer','os_id'=>'nullable|string|max:100','payment_method'=>'required|string|in:stripe,mobilepay,paypal']);$p=DB::table('billing_products')->where('id',$d['product_id'])->where('active',true)->first();abort_unless($p,404);$gateway=Schema::hasTable('payment_gateways')?DB::table('payment_gateways')->where('gateway',$d['payment_method'])->where('enabled',true)->first():null;if(!$gateway)return back()->withInput()->withErrors(['payment_method'=>'Den valgte betalingsmetode er ikke aktiv.']);if(($p->product_type??'game')==='vps'&&empty($d['os_id']))return back()->withInput()->withErrors(['os_id'=>'Vælg et operativsystem til VPS’en.']);$now=now();$orderId=DB::table('billing_orders')->insertGetId(['user_id'=>$u->id,'product_id'=>$p->id,'status'=>'pending','amount'=>$p->price,'currency'=>$p->currency,'payment_method'=>$d['payment_method'],'created_at'=>$now,'updated_at'=>$now]);$invoiceId=DB::table('invoices')->insertGetId(['user_id'=>$u->id,'order_id'=>$orderId,'number'=>'NX-'.now()->format('Ym').'-'.strtoupper(Str::random(6)),'status'=>'unpaid','subtotal'=>$p->price,'tax'=>0,'total'=>$p->price,'currency'=>$p->currency,'due_at'=>now()->addDays(7),'created_at'=>$now,'updated_at'=>$now]);DB::table('invoice_items')->insert(['invoice_id'=>$invoiceId,'description'=>$p->name.' ('.$p->billing_cycle.')','quantity'=>1,'unit_price'=>$p->price,'total'=>$p->price,'created_at'=>$now,'updated_at'=>$now]);if(($p->product_type??'game')==='vps'&&Schema::hasTable('vps_services')){$provider=DB::table('vps_providers')->where('active',true)->first();DB::table('vps_services')->insert(['user_id'=>$u->id,'order_id'=>$orderId,'product_id'=>$p->id,'provider_id'=>$provider->id??0,'os_id'=>$d['os_id'],'status'=>'awaiting_payment','created_at'=>$now,'updated_at'=>$now]);}return redirect('/client/checkout/'.$invoiceId)->with('success','Ordren er oprettet. Vælg betaling for at færdiggøre bestillingen.');} public function checkout(Request $r,int $invoice){$i=DB::table('invoices')->where('id',$invoice)->where('user_id',$r->user()->id)->first();abort_unless($i,404);$order=$i->order_id?DB::table('billing_orders')->where('id',$i->order_id)->where('user_id',$r->user()->id)->first():null;$gateways=Schema::hasTable('payment_gateways')?DB::table('payment_gateways')->where('enabled',true)->orderBy('sort_order')->get():collect();return view('client.checkout',['user'=>$r->user(),'invoice'=>$i,'order'=>$order,'gateways'=>$gateways]);} public function createTicket(Request $r){$u=$r->user();$d=$r->validate(['subject'=>'required|string|max:190','message'=>'required|string|max:10000','department'=>'nullable|in:support,billing,sales','priority'=>'nullable|in:low,normal,high']);$now=now();$id=DB::table('tickets')->insertGetId(['user_id'=>$u->id,'subject'=>$d['subject'],'department'=>$d['department']??'support','priority'=>$d['priority']??'normal','status'=>'open','created_at'=>$now,'updated_at'=>$now]);DB::table('ticket_messages')->insert(['ticket_id'=>$id,'user_id'=>$u->id,'message'=>$d['message'],'staff'=>false,'created_at'=>$now,'updated_at'=>$now]);return redirect('/client/tickets/'.$id);} public function ticket(Request $r,int $id){$u=$r->user();$ticket=DB::table('tickets')->where('id',$id)->where('user_id',$u->id)->first();abort_unless($ticket,404);$messages=DB::table('ticket_messages')->where('ticket_id',$id)->orderBy('id')->get();return view('client.ticket',compact('u','ticket','messages'))->with('user',$u);} public function replyTicket(Request $r,int $id){$u=$r->user();$ticket=DB::table('tickets')->where('id',$id)->where('user_id',$u->id)->first();abort_unless($ticket,404);abort_if($ticket->status==='closed',422);$d=$r->validate(['message'=>'required|string|max:10000']);DB::table('ticket_messages')->insert(['ticket_id'=>$id,'user_id'=>$u->id,'message'=>$d['message'],'staff'=>false,'created_at'=>now(),'updated_at'=>now()]);DB::table('tickets')->where('id',$id)->update(['status'=>'customer_reply','updated_at'=>now()]);return back();} public function closeTicket(Request $r,int $id){DB::table('tickets')->where('id',$id)->where('user_id',$r->user()->id)->update(['status'=>'closed','updated_at'=>now()]);return redirect('/client#tickets');}}
